    PREEDIT_UL: PREEDIT_UL2,
    PREEDIT_ACTIVE_BG: PREEDIT_ACTIVE_BG2,
    PREEDIT_CARET: PREEDIT_CARET2,
    PREEDIT_FG: PREEDIT_FG2,
