    fontState,
    defaultBg,
    selectionState,
    selectionForRow: selectionForRow2,
    getSearchViewportMatches,
    pushRect: pushRect2,
    selectionBackgroundColor,
    selectionForegroundColor,
    searchMatchBackgroundColor,
    searchCurrentMatchBackgroundColor,
    searchMatchTextColor,
    searchCurrentMatchTextColor,
    STYLE_BOLD,
    STYLE_ITALIC,
    STYLE_FAINT,
    STYLE_BLINK,
    STYLE_INVERSE,
    STYLE_INVISIBLE,
    STYLE_STRIKE,
    STYLE_OVERLINE,
    STYLE_UNDERLINE_MASK,
    decodeRGBAWithCache: decodeRGBAWithCache2,
    brighten: brighten2,
    BOLD_BRIGHTEN,
    fade: fade2,
    FAINT_ALPHA,
    linkState,
    drawUnderlineStyle: drawUnderlineStyle2,
    drawStrikethrough: drawStrikethrough2,
    drawOverline: drawOverline2,
    KITTY_PLACEHOLDER_CP,
    isSpaceCp: isSpaceCp2,
    shouldMergeTrailingClusterCodepoint: shouldMergeTrailingClusterCodepoint2,
