    drawBoxDrawing: drawBoxDrawing2,
    isBraille: isBraille2,
    drawBraille: drawBraille2,
    isPowerline: isPowerline2,
    drawPowerline: drawPowerline2,
    pickFontIndexForText: pickFontIndexForText2,
